head.script:
scwin.showData = function() {
    alert("wframe_SKT-261_(WSQ-916)_sub");
};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.logMessage1 = "";
    window.logMessage2 = "";
    window.logMessage3 = "";
    window.logMessage4 = "";
    // 정상 동작
    console.log("parent.ibx_id Runtime Id : " + scwin.$w.getRuntimeId("ibx_id", "parent"));
    window.logMessage1 = "parent.ibx_id Runtime Id : " + scwin.$w.getRuntimeId("ibx_id", "parent");
    console.log("ibx_name Runtime Id : " + scwin.$w.getRuntimeId("ibx_name"));
    window.logMessage2 = "ibx_name Runtime Id : " + scwin.$w.getRuntimeId("ibx_name");
    // 비정상 동작
    console.log("scwin Runtime Id : " + scwin.$w.getRuntimeId("scwin"));
    window.logMessage3 = "scwin Runtime Id : " + scwin.$w.getRuntimeId("scwin");
    console.log("parent.scwin Runtime Id : " + scwin.$w.getRuntimeId("scwin", "parent"));
    window.logMessage4 = "parent.scwin Runtime Id : " + scwin.$w.getRuntimeId("scwin", "parent");
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
